insert into public.tool_pages (slug,title,description,intro,how_to,faq,seo_title,seo_description) values
('word-counter','Word Counter','Count words, characters, sentences, paragraphs, reading time, and keyword density.','Analyze writing privately in your browser. Live totals help evaluate length and readability while keyword density highlights repeated terms without sending draft text to the server.','["Paste or type text into the editor.","Review the live statistics and keyword list.","Copy the revised text when it is ready."]','[{"question":"Is my text uploaded?","answer":"No. Text analysis runs locally in your browser."},{"question":"How is reading time calculated?","answer":"The estimate uses an average pace of 200 words per minute."}]','Word Counter — Free Online Writing Analysis','Count words, characters, sentences, paragraphs, reading time, and keyword density instantly in your browser.'),
('character-counter','Character Counter','See live character totals with and without spaces, plus words and lines.','Check length limits for snippets, forms, messages, and social posts. The tool counts every character locally and separately reports characters without whitespace.','["Enter or paste your text.","Compare totals with and without spaces.","Edit until the text fits your limit."]','[{"question":"Is punctuation counted?","answer":"Yes. Punctuation and symbols are characters."},{"question":"Is text saved?","answer":"No. Counting happens in the browser."}]','Character Counter — Count Letters and Spaces','Count characters with and without spaces, words, and lines instantly with this free private browser tool.'),
('website-word-counter','Web Page Word Counter','Enter a public URL to estimate its visible word count and reading time.','Analyze readable text from a public HTML page for editorial research. Private addresses, oversized pages, and redirect chains are blocked to protect the service.','["Paste the final public page URL.","Select Count words and wait for the secure request.","Review words, characters, and reading time."]','[{"question":"Can it read private pages?","answer":"No. Only public HTTP and HTTPS pages are supported."},{"question":"Why can totals differ?","answer":"JavaScript-rendered and hidden content can affect visible totals."}]','Website Word Counter — Analyze a Public URL','Count readable words and estimate reading time for a public web page URL safely and quickly.'),
('auto-capitalize','Auto Capitalize Sentences','Fix sentence capitalization or convert text to title, upper, or lower case.','Clean inconsistent casing with sentence, title, upper, and lower modes. Compare the original, copy the result, or download a UTF-8 text file.','["Paste the text to transform.","Choose a capitalization mode.","Copy or download the converted text."]','[{"question":"Does it recognize names?","answer":"Automatic rules cannot identify every proper noun, so review names."},{"question":"Can I download the result?","answer":"Yes, as a plain UTF-8 text file."}]','Auto Capitalize Sentences — Free Case Converter','Fix sentence capitalization or change text to title, uppercase, or lowercase online.'),
('compare-text','Compare Text','Compare two passages and highlight additions, removals, and unchanged words.','Review revisions with a readable word-level difference view. Source text stays in the browser and additions and removals use distinct accessible colors.','["Paste the original into the left editor.","Paste the revision into the right editor.","Review highlighted additions and removals."]','[{"question":"Is comparison private?","answer":"Yes. The browser performs the comparison."},{"question":"What type of diff is used?","answer":"A word-level longest-common-subsequence comparison."}]','Compare Text Online — Free Difference Checker','Compare two text versions and highlight added, removed, and unchanged words privately online.'),
('pdf-to-word','PDF to Word Converter','Turn a PDF into an editable DOCX document.','Extract selectable text from a PDF into an editable Word document. Complex visual formatting and scanned image-only pages may require manual review or OCR.','["Upload one PDF up to 20 MB.","Start the DOCX conversion.","Download and review the editable document."]','[{"question":"Are files retained?","answer":"Temporary files are deleted immediately after the response and never later than one hour."},{"question":"Does it support scans?","answer":"Image-only scans require OCR, which is not included in this converter."}]','PDF to Word Converter — Free PDF to DOCX','Convert selectable PDF text to an editable DOCX file online with short-lived secure processing.'),
('word-to-pdf','Word to PDF Converter','Create a portable PDF from a DOC or DOCX file.','Render Word documents as portable PDFs using a server-side office engine. Embedded fonts and specialized layout features can vary, so check the downloaded result.','["Upload a DOC or DOCX file up to 20 MB.","Start PDF conversion.","Download and compare the PDF with the source."]','[{"question":"Is this free?","answer":"Yes, within the stated fair-use and file-size limits."},{"question":"How long are files kept?","answer":"They are removed immediately after processing and never later than one hour."}]','Word to PDF Converter — Free DOCX to PDF','Convert DOC and DOCX Word files to PDF online with secure temporary processing.'),
('pdf-to-png','PDF to PNG Converter','Render PDF pages as crisp PNG images.','Turn every PDF page into a high-quality PNG image and receive multi-page output in a convenient ZIP archive.','["Upload one PDF up to 20 MB.","Start PNG rendering.","Download the ZIP and extract each page image."]','[{"question":"How are multiple pages delivered?","answer":"All page images are bundled in one ZIP."},{"question":"Are files private?","answer":"Temporary files are automatically deleted within one hour."}]','PDF to PNG Converter — Free Page Images','Convert every PDF page to a crisp PNG image and download all pages in a ZIP archive.'),
('pdf-to-jpg','PDF to JPG Converter','Render PDF pages as compact JPG images.','Render each PDF page as a compressed JPG for sharing, previews, and web use. Multi-page documents are returned as a ZIP archive.','["Upload one PDF up to 20 MB.","Start JPG rendering.","Download the ZIP of page images."]','[{"question":"How are pages delivered?","answer":"Page JPG files are bundled in a ZIP archive."},{"question":"Can quality change?","answer":"JPG uses lossy compression for smaller output."}]','PDF to JPG Converter — Free Page Images','Convert PDF pages to compact JPG images online and download multi-page output as a ZIP.'),
('pdf-to-excel','PDF to Excel Converter','Extract readable PDF text into an XLSX workbook.','Extract selectable text and detect spacing-separated columns to create an Excel workbook. Results from complex tables should be checked carefully.','["Upload a text-based PDF up to 20 MB.","Start XLSX extraction.","Download and review rows and columns."]','[{"question":"Does it use OCR?","answer":"No. Scanned image-only pages require OCR first."},{"question":"Will every table be exact?","answer":"Complex merged cells and visual layouts may require correction."}]','PDF to Excel Converter — Extract to XLSX','Extract selectable PDF text and tables into an editable XLSX workbook online.'),
('excel-to-pdf','Excel to PDF Converter','Export XLS or XLSX spreadsheets as PDF.','Render an Excel workbook through a compatible office engine to produce a portable PDF for viewing or sharing.','["Upload an XLS or XLSX file up to 20 MB.","Start PDF conversion.","Download and inspect page breaks and scaling."]','[{"question":"Are formulas recalculated?","answer":"The office engine may recalculate supported formulas."},{"question":"Are uploads stored?","answer":"No. Temporary files are removed within one hour."}]','Excel to PDF Converter — Free XLSX to PDF','Convert XLS and XLSX spreadsheets to PDF online with secure temporary file processing.'),
('ppt-to-pdf','PPT to PDF Converter','Export PowerPoint presentations as PDF.','Turn PPT or PPTX slides into a portable PDF. Animations and video cannot appear in a static PDF, but slide appearance is preserved where supported.','["Upload a PPT or PPTX up to 20 MB.","Start PDF conversion.","Download and review the static slides."]','[{"question":"Are animations preserved?","answer":"No. PDF output is static."},{"question":"Are fonts always identical?","answer":"Unavailable fonts may be substituted by the server."}]','PPT to PDF Converter — Free PowerPoint Export','Convert PPT and PPTX PowerPoint presentations to a portable PDF online.'),
('pdf-to-ppt','PDF to PPT Converter','Turn PDF pages into PowerPoint slides.','Place each rendered PDF page onto a widescreen PowerPoint slide. The visual page is preserved as an image rather than editable source elements.','["Upload one PDF up to 20 MB.","Start PPTX conversion.","Download the presentation with one slide per page."]','[{"question":"Is slide text editable?","answer":"Pages are placed as slide images, so source text is not independently editable."},{"question":"What slide size is used?","answer":"The output uses a widescreen presentation layout."}]','PDF to PPT Converter — PDF Pages to Slides','Convert PDF pages into a widescreen PPTX presentation with one rendered page per slide.'),
('jpg-to-pdf','JPG to PDF Converter','Combine one or more JPG images into a PDF.','Combine up to twenty JPG images into a single PDF while scaling oversized images to a practical page boundary.','["Choose or drop up to 20 JPG images totaling 20 MB.","Start PDF creation.","Download the combined document."]','[{"question":"Can I combine several images?","answer":"Yes, up to twenty within the total size limit."},{"question":"Does this reduce quality?","answer":"JPEG image data is embedded without additional lossy recompression."}]','JPG to PDF Converter — Combine Images','Combine one or more JPG images into a single PDF online, with a 20 MB total upload limit.'),
('png-to-pdf','PNG to PDF Converter','Combine one or more PNG images into a PDF.','Combine up to twenty PNG graphics into one PDF while preserving transparency support during embedding and scaling large pages sensibly.','["Choose or drop up to 20 PNG files totaling 20 MB.","Start PDF creation.","Download the combined PDF."]','[{"question":"Can I combine several PNGs?","answer":"Yes, up to twenty within the total size limit."},{"question":"Are files stored?","answer":"Temporary data is removed immediately after processing and never later than one hour."}]','PNG to PDF Converter — Combine Images','Combine one or more PNG images into a single PDF online with secure temporary processing.'),
('color-wheel','Color Wheel','Pick colors and generate complementary, analogous, triadic, and monochromatic palettes.','Choose hue, saturation, and lightness visually, then copy production-ready HEX, RGB, and HSL values. Generate established color relationships without sending selections to a server.','["Choose a color on the wheel and adjust lightness.","Select a palette relationship.","Copy the primary value or an individual swatch."]','[{"question":"Which CSS format is best?","answer":"HEX, RGB, and HSL all work; HSL is often easiest to adjust."},{"question":"Are palettes saved?","answer":"No. Copy the values you want to retain."}]','Color Wheel — HEX, RGB, HSL Palette Generator','Pick a color, convert HEX, RGB, and HSL values, and generate harmonious palettes online.')
insert into public.content_pages (slug,title,description,body,seo_title) values
('privacy-policy','Privacy Policy','How Figimi Tools handles text, uploaded files, analytics, advertising, and contact information.',E'## Overview\n\nText tools run locally in your browser.\n\n## File conversion and retention\n\nUploaded files are used only for the requested conversion, processed in isolated temporary storage, removed immediately after the response whenever possible, and automatically deleted no later than one hour after upload. Files are not used for advertising, model training, or resale.\n\n## Analytics and advertising\n\nIf enabled, Google Analytics, Google Tag Manager, and Google AdSense may process cookies and limited device or usage information. Cloudflare may process network data for security and delivery.\n\n## Your choices\n\nYou can block nonessential cookies in your browser and contact us to request access, correction, or deletion of personal data we hold. Last updated July 22, 2026.','Privacy Policy'),
('terms-of-service','Terms of Service','Rules and conditions for using Figimi Tools and its free conversion services.',E'## Permitted use\n\nUse the service lawfully and only with files you are authorized to process. Do not overload, probe, or bypass service controls.\n\n## Conversion limits\n\nResults may lose formatting, formulas, fonts, or metadata. Keep your original and inspect the output.\n\n## Disclaimer\n\nThe service is provided as is, without a guarantee of availability or fitness for a particular purpose.','Terms of Service'),
('about','About Us','Why Figimi Tools builds fast, private, and accessible utilities for everyday digital work.',E'## Useful software should feel simple\n\nFigimi Tools provides focused utilities for writers, students, designers, and office teams. We explain each tool, disclose its limits, support mobile devices, and avoid unnecessary registration.\n\n## Privacy and quality\n\nBrowser tools keep text on your device. File tools use short-lived server processing. We publish original guides and recommend checking important output against the source.','About Figimi Tools')
insert into public.posts (id,title,slug,meta_description,seo_title,category,tags,author,body,status,published_at)
